const D = { energy:.6, scale:1, hue:24, speed:1, density:.5, x:.5, y:.5, drift:.5, bar:.5, style:'super8', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u=Math.min(width,height);
// soft radial sprite once
if(!S.spr){ const R=80; const s=createGraphics(R*2,R*2); s.pixelDensity(1); s.noStroke();
  for(let r=R;r>0;r--){ const a=Math.pow(1-r/R,1.7)*255; s.fill(255,255,255,a*0.85); s.ellipse(R,R,r*2,r*2); }
  S.spr=s; }
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed;
  const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
  S.hoff=fr(1);
  // each leak: edge anchor(0..1 along perimeter idea via ex,ey), phase, wobble rate, hue offset, size
  S.lk=[]; for(let k=0;k<7;k++){ const edge=Math.floor(fr(k*6+2)*4);
    let ex,ey; const p=fr(k*6+3);
    if(edge===0){ex=p;ey=0;} else if(edge===1){ex=1;ey=p;} else if(edge===2){ex=p;ey=1;} else {ex=0;ey=p;}
    S.lk.push([ex,ey,fr(k*6+4)*6.28,0.4+fr(k*6+5)*0.9,fr(k*6+6),0.5+fr(k*6+7||k)*0.8]); }
}
const t=K.t*(0.3+P.speed*0.5);
const style=P.style;
// palette of leak hues (in HSB degrees)
const pals = { super8:[18,8,34,46], ektachrome:[315,190,175,95], halation:[6,350,20,40], prism:[0,60,140,260], bw_fog:[40,40,40,40] };
const pal = pals[style]||pals.super8;
const nleak=2+Math.round(P.density*5);
const amp=0.5+P.energy*1.0+K.intensity*0.3+A.rms*0.5;
const sat = style==='bw_fog'?12 : 70;

push(); blendMode(ADD); imageMode(CENTER); noStroke();
// --- big soft edge leaks (broad area element) ---
for(let k=0;k<nleak;k++){ const lk=S.lk[k];
  const wob=(0.5+P.drift);
  const lx=(lk[0] + wob*0.08*Math.sin(t*0.31*lk[3]+lk[2]) )*width;
  const ly=(lk[1] + wob*0.08*Math.cos(t*0.27*lk[3]+lk[2]*1.3))*height;
  const breathe=0.45+0.55*Math.abs(Math.sin(t*0.19*lk[3]+lk[4]*6.28));
  const sz=u*(0.7+1.1*lk[5])*P.scale;
  const hh=(P.hue + pal[(k%4)] + K.section*3)%360;
  const a=amp*breathe;
  tint(hh, sat, 100, Math.min(100, 30*a));
  image(S.spr, lx, ly, sz, sz*(0.7+0.5*lk[5]));
}
// --- slow over-exposure bar sweeping across (partial, non-strobe) ---
if(P.bar>0.02){
  const sweep=(0.5+0.5*Math.sin(t*0.23+1.1));
  const bx=sweep*width;
  const bw=u*(0.25+P.bar*0.5);
  const ba=amp*P.bar*(0.4+0.3*Math.sin(t*0.7));
