  for(let s=0;s<5;s++){ const off=(s-2)*bw*0.4;
    tint(hh, sat*0.6, 100, Math.min(100, 14*ba*(1-Math.abs(s-2)/3)));
    image(S.spr, bx+off, height*0.5 + u*0.1*Math.sin(t*0.4), bw, height*1.4);
  }
}
imageMode(CORNER); blendMode(BLEND); pop();
// subtle emulsion grain flicker (very low, non-strobe)
push(); blendMode(ADD); noStroke();
const gflk=0.5+0.5*Math.sin(t*1.9)+0.3*Math.sin(t*3.3+2);
fill(P.hue%360, sat*0.3, 100, 2.2+1.4*gflk*P.energy); rect(0,0,width,height);
blendMode(BLEND); pop();
